#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;

int main(){
    int xi, yi, xf, yf;
    if (scanf("%d %d %d %d", &xi, &yi, &xf, &yf) != 4) return 0;
    int n;
    if (scanf("%d", &n) != 1) return 0;

    vector<int> RX1(n), RY1(n), RX2(n), RY2(n);
    vector<int> xs, ys;
    xs.reserve(2 * n + 2); ys.reserve(2 * n + 2);
    xs.push_back(xi); xs.push_back(xf);
    ys.push_back(yi); ys.push_back(yf);
    for (int i = 0; i < n; ++i){
        scanf("%d %d %d %d", &RX1[i], &RY1[i], &RX2[i], &RY2[i]);
        xs.push_back(RX1[i]); xs.push_back(RX2[i]);
        ys.push_back(RY1[i]); ys.push_back(RY2[i]);
    }
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    const int nx = (int)xs.size(), ny = (int)ys.size();
    const size_t G = (size_t)nx * (size_t)ny;

    // indices por retangulo no grid comprimido
    vector<int> rowA(n), rowB(n), hxA(n), hxB(n), colA(n), colB(n), vyA(n), vyB(n);
    for (int r = 0; r < n; ++r){
        int ya = (int)(lower_bound(ys.begin(), ys.end(), RY1[r]) - ys.begin());
        int ye = (int)(upper_bound(ys.begin(), ys.end(), RY2[r]) - ys.begin());
        int xa = (int)(lower_bound(xs.begin(), xs.end(), RX1[r]) - xs.begin());
        int xe = (int)(upper_bound(xs.begin(), xs.end(), RX2[r]) - xs.begin());
        rowA[r] = ya;  rowB[r] = ye - 1;  // linhas j com ys[j] em [RY1,RY2] (borda conta)
        hxA[r]  = xa;  hxB[r]  = xe - 2;  // celulas i com [xs[i],xs[i+1]] dentro de [RX1,RX2]
        colA[r] = xa;  colB[r] = xe - 1;  // colunas i com xs[i] em [RX1,RX2]
        vyA[r]  = ya;  vyB[r]  = ye - 2;  // celulas j com [ys[j],ys[j+1]] dentro de [RY1,RY2]
    }

    // covH[i][j]: segmento entre (i,j)-(i+1,j) coberto; covV[i][j]: entre (i,j)-(i,j+1)
    vector<unsigned char> covH(G, 0), covV(G, 0);
    vector<int> diff((size_t)max(nx, ny) + 2, 0);

    for (int j = 0; j < ny; ++j){
        for (int t = 0; t <= nx; ++t) diff[t] = 0;
        for (int r = 0; r < n; ++r)
            if (rowA[r] <= j && j <= rowB[r] && hxA[r] <= hxB[r]){
                ++diff[hxA[r]];
                --diff[hxB[r] + 1];
            }
        int run = 0;
        for (int i = 0; i + 1 < nx; ++i){
            run += diff[i];
            if (run > 0) covH[(size_t)i * ny + j] = 1;
        }
    }
    for (int i = 0; i < nx; ++i){
        for (int t = 0; t <= ny; ++t) diff[t] = 0;
        for (int r = 0; r < n; ++r)
            if (colA[r] <= i && i <= colB[r] && vyA[r] <= vyB[r]){
                ++diff[vyA[r]];
                --diff[vyB[r] + 1];
            }
        int run = 0;
        for (int j = 0; j + 1 < ny; ++j){
            run += diff[j];
            if (run > 0) covV[(size_t)i * ny + j] = 1;
        }
    }

    const int sid = (int)(lower_bound(xs.begin(), xs.end(), xi) - xs.begin()) * ny
                  + (int)(lower_bound(ys.begin(), ys.end(), yi) - ys.begin());
    const int tid = (int)(lower_bound(xs.begin(), xs.end(), xf) - xs.begin()) * ny
                  + (int)(lower_bound(ys.begin(), ys.end(), yf) - ys.begin());

    // Dijkstra nos vertices do grid; aresta coberta custa 0, senao custa o comprimento
    vector<int> dist(G, 0x3f3f3f3f);
    priority_queue<ull, vector<ull>, greater<ull> > pq;
    dist[sid] = 0;
    pq.push((ull)sid);
    int ans = 0;
    while (!pq.empty()){
        ull k = pq.top(); pq.pop();
        const int d = (int)(k >> 22);
        const int v = (int)(k & ((1ull << 22) - 1));
        if (d > dist[v]) continue;
        if (v == tid){ ans = d; break; }
        const int i = v / ny, j = v - i * ny;
        const size_t b = (size_t)i * ny + j;
        if (i + 1 < nx){
            const int nd = d + (covH[b] ? 0 : xs[i + 1] - xs[i]);
            if (nd < dist[v + ny]){ dist[v + ny] = nd; pq.push(((ull)nd << 22) | (ull)(v + ny)); }
        }
        if (i > 0){
            const int nd = d + (covH[b - ny] ? 0 : xs[i] - xs[i - 1]);
            if (nd < dist[v - ny]){ dist[v - ny] = nd; pq.push(((ull)nd << 22) | (ull)(v - ny)); }
        }
        if (j + 1 < ny){
            const int nd = d + (covV[b] ? 0 : ys[j + 1] - ys[j]);
            if (nd < dist[v + 1]){ dist[v + 1] = nd; pq.push(((ull)nd << 22) | (ull)(v + 1)); }
        }
        if (j > 0){
            const int nd = d + (covV[b - 1] ? 0 : ys[j] - ys[j - 1]);
            if (nd < dist[v - 1]){ dist[v - 1] = nd; pq.push(((ull)nd << 22) | (ull)(v - 1)); }
        }
    }
    printf("%d\n", ans);
    return 0;
}
